using System.Data;
using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage;
using Shop.SharedKernel;
namespace Shop.Modules.Credit;
public sealed class CreditUpfrontService(CreditDbContext db,CreditScheduleService schedules,ICreditOrderScheduleSource sourceReader,ICreditUpfrontProtection protection,ICreditUpfrontOrderStages stages,TimeProvider clock)
{
    private sealed record Origin(string Id,string OwnerId,string OrderId,string OriginalScheduleId,string QuoteFingerprint,string FinancialHash,long RequiredAmountRial,string ActorId,DateTimeOffset RecordedAt);
    private sealed record EventSeal(string Id,string ConfirmationId,string OrderId,string ScheduleId,int Sequence,string Action,string State,long RequiredAmountRial,long AcknowledgedAmountRial,string ActorId,DateTimeOffset OccurredAt,DateTimeOffset RecordedAt,string OrderVersion,string ScheduleVersion,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.Never)]string? PreviousVersion,string Reference,string Note,bool AcknowledgedClosedOrder,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingDefault)]bool AcknowledgedCommittedOrder=false);
    private sealed record Basis(CreditOrderScheduleSource Source,CreditScheduleRevisionData? Schedule,long Required,bool CommittedAmendable);
    private static string Json<T>(T value)=>JsonSerializer.Serialize(value,CreditScheduleFacts.Json);
    private static string Version(CreditUpfrontEvent e)=>Convert.ToBase64String(e.Version);
    private static bool Open(CreditOrderScheduleSource s,DateTimeOffset now)=>s.State=="AwaitingPayment"&&s.ExpiresAt>now;
    private static bool AmendableState(CreditOrderScheduleSource s)=>s.State is"AwaitingPayment"or"Expired"or"Cancelled";
    private void Root(){if(db.Database.CurrentTransaction?.GetDbTransaction().IsolationLevel!=IsolationLevel.Serializable)throw new InvalidOperationException("Upfront confirmations require the root audited Serializable Sales/Credit transaction.");}
    private T Decode<T>(string purpose,string principal,string order,string id,byte[] bytes)
    {
        try{return JsonSerializer.Deserialize<T>(protection.Unprotect(purpose,principal,order,id,bytes),CreditScheduleFacts.Json)??throw CreditUpfrontRules.Unavailable();}catch(Exception e)when(e is JsonException or NullReferenceException){throw CreditUpfrontRules.Unavailable();}
    }
    private async Task<Basis> Source(string owner,string order,CancellationToken ct)
    {
        Root();owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);var page=await schedules.PageAsync(owner,order,false,ct);var source=await sourceReader.LockAndReadAsync(owner,order,ct);if(source.OwnerId!=owner||source.OrderId!=order||source.OrderVersion!=page.OrderVersion||source.State!=page.OrderState)throw CreditUpfrontRules.Unavailable();var amount=CreditUpfrontRules.Required(source.PayableTotalRial,source.Installments.Select(x=>x.AmountRial).ToArray());if(page.Current is{}s&&(s.OrderId!=order||s.QuoteFingerprint!=source.QuoteFingerprint||s.Calculation.UpfrontTotalRial!=CreditUpfrontRules.Rial(amount)))throw CreditUpfrontRules.Unavailable();var amendable=false;if(source.State=="CreditApproved"){var stage=await stages.ReadAsync(owner,order,ct);if(stage.OrderId!=order||stage.OrderVersion!=source.OrderVersion||stage.State!=source.State)throw CreditUpfrontRules.Unavailable();amendable=stage.ShipmentState is null or"packed";}return new(source,page.Current,amount,amendable);
    }
    private IQueryable<CreditUpfrontConfirmation> Confirmations(string order)=>db.UpfrontConfirmations.FromSqlInterpolated($"SELECT * FROM [credit].[UpfrontConfirmations] WITH (READCOMMITTEDLOCK) WHERE [OrderId]={order}").AsNoTracking();
    private IQueryable<CreditUpfrontEvent> Events(string id)=>db.UpfrontEvents.FromSqlInterpolated($"SELECT * FROM [credit].[UpfrontEvents] WITH (READCOMMITTEDLOCK) WHERE [ConfirmationId]={id}").AsNoTracking();
    private IQueryable<CreditUpfrontCommand> Commands=>db.UpfrontCommands.FromSqlRaw("SELECT * FROM [credit].[UpfrontCommands] WITH (READCOMMITTEDLOCK)").AsNoTracking();
    private static Origin OriginData(CreditUpfrontConfirmation c)=>new(c.Id,c.OwnerId,c.OrderId,c.OriginalScheduleId,c.QuoteFingerprint,c.FinancialHash,c.RequiredAmountRial,c.ActorId,c.RecordedAt);
    private void VerifyOrigin(CreditUpfrontConfirmation c,Basis b)
    {
        var origin=Decode<Origin>("origin",c.OwnerId,c.OrderId,c.Id,c.ProtectedOrigin);if(origin!=OriginData(c)||c.OwnerId!=b.Source.OwnerId||c.OrderId!=b.Source.OrderId||c.QuoteFingerprint!=b.Source.QuoteFingerprint||c.FinancialHash!=CreditScheduleFacts.FinancialHash(b.Source)||c.RequiredAmountRial!=b.Required||c.RecordedAt<b.Source.CreatedAt||c.RecordedAt>=b.Source.ExpiresAt)throw CreditUpfrontRules.Unavailable();
    }
    private static CreditUpfrontSummary Summary(CreditUpfrontEvent e)=>new(e.Id,e.ConfirmationId,e.OrderId,e.Sequence,e.Action,e.State,CreditUpfrontRules.Rial(e.RequiredAmountRial),CreditUpfrontRules.Rial(e.AcknowledgedAmountRial),Version(e),e.OccurredAt,e.RecordedAt);
    private (CreditUpfrontEventData Data,EventSeal Seal) EventData(CreditUpfrontConfirmation c,CreditUpfrontEvent e)
    {
        var s=Decode<EventSeal>("event",c.OwnerId,c.OrderId,e.Id,e.ProtectedEvent);
        if(s.Id!=e.Id||s.ConfirmationId!=c.Id||e.ConfirmationId!=c.Id||s.OrderId!=c.OrderId||e.OrderId!=c.OrderId||s.ScheduleId!=e.ScheduleId||s.Sequence!=e.Sequence||s.Action!=e.Action||s.State!=e.State||s.RequiredAmountRial!=c.RequiredAmountRial||e.RequiredAmountRial!=c.RequiredAmountRial||s.AcknowledgedAmountRial!=e.AcknowledgedAmountRial||s.ActorId!=e.ActorId||s.OccurredAt!=e.OccurredAt||s.RecordedAt!=e.RecordedAt||e.RecordedAt<c.RecordedAt||e.OccurredAt>e.RecordedAt||e.Version.Length!=8)throw CreditUpfrontRules.Unavailable();
        try{CreditApplicationRules.Version(s.OrderVersion);CreditApplicationRules.Version(s.ScheduleVersion);if(s.PreviousVersion is{}v)CreditApplicationRules.Version(v);CreditUpfrontRules.Text(s.Reference,256,s.Action=="ConfirmReceipt");CreditUpfrontRules.Text(s.Note,500,s.Action=="RevokeConfirmation"||s.AcknowledgedCommittedOrder);if(s.AcknowledgedCommittedOrder&&(s.PreviousVersion is null||s.AcknowledgedClosedOrder))throw CreditUpfrontRules.Unavailable();if(s.Action!="ConfirmReceipt"&&s.Reference.Length!=0||e.AcknowledgedAmountRial!=CreditUpfrontRules.Acknowledged(e.State,e.RequiredAmountRial))throw CreditUpfrontRules.Unavailable();}catch(BusinessException){throw CreditUpfrontRules.Unavailable();}
        return(new(Summary(e),s.Reference,s.Note,s.OrderVersion,s.ScheduleVersion,s.PreviousVersion,s.AcknowledgedClosedOrder,s.AcknowledgedCommittedOrder),s);
    }
    private CreditUpfrontResult Receipt(CreditUpfrontCommand c)
    {
        var raw=protection.Unprotect("receipt",c.ActorId,c.OrderId,c.CommandId,c.ProtectedResult);try{if(CreditApplicationRules.Hash(raw)!=c.ResultHash)throw CreditUpfrontRules.Unavailable();var r=JsonSerializer.Deserialize<CreditUpfrontResult>(raw,CreditScheduleFacts.Json)??throw CreditUpfrontRules.Unavailable();var s=r.Event.Summary;if(r.SchemaVersion!=1||r.Replayed||r.CommandId!=c.CommandId||r.OrderId!=c.OrderId||s.OrderId!=c.OrderId||s.ConfirmationId!=c.ConfirmationId||s.Id!=c.EventId||s.RecordedAt!=c.At||r.BankVerified||r.CanPay||r.CanFulfill||s.BankVerified)throw CreditUpfrontRules.Unavailable();return r;}catch(Exception e)when(e is JsonException or NullReferenceException){throw CreditUpfrontRules.Unavailable();}
    }
    private async Task<CreditUpfrontEventData[]> VerifiedEvents(CreditUpfrontConfirmation c,Basis b,CancellationToken ct)
    {
        VerifyOrigin(c,b);var rows=await Events(c.Id).OrderBy(x=>x.Sequence).Take(CreditUpfrontRules.MaximumEvents+1).ToArrayAsync(ct);if(rows.Length is<1 or>CreditUpfrontRules.MaximumEvents)throw CreditUpfrontRules.Unavailable();var commands=await Commands.Where(x=>x.ConfirmationId==c.Id).Take(CreditUpfrontRules.MaximumEvents+1).ToArrayAsync(ct);if(commands.Length!=rows.Length)throw CreditUpfrontRules.Unavailable();var data=new List<CreditUpfrontEventData>();CreditUpfrontEvent? previous=null;
        foreach(var e in rows){var (d,s)=EventData(c,e);if(e.Sequence!=data.Count+1||s.PreviousVersion!=(previous is null?null:Version(previous))||e.RecordedAt<(previous?.RecordedAt??c.RecordedAt)||e.OccurredAt<(s.AcknowledgedCommittedOrder?b.Source.CreatedAt:previous?.OccurredAt??b.Source.CreatedAt))throw CreditUpfrontRules.Unavailable();try{if(CreditUpfrontRules.Next(previous?.State,e.Action,c.RequiredAmountRial)!=e.State)throw CreditUpfrontRules.Unavailable();}catch(BusinessException){throw CreditUpfrontRules.Unavailable();}var cmd=commands.SingleOrDefault(x=>x.EventId==e.Id)??throw CreditUpfrontRules.Unavailable();var receipt=Receipt(cmd);if(cmd.OwnerId!=c.OwnerId||cmd.OrderId!=c.OrderId||cmd.ActorId!=e.ActorId||Json(receipt.Event)!=Json(d))throw CreditUpfrontRules.Unavailable();data.Add(d);previous=e;}return data.ToArray();
    }
    public async Task<CreditUpfrontResult> WriteAsync(string actor,string owner,string order,string commandId,CreditUpfrontInput input,CancellationToken ct)
    {
        actor=CreditApplicationRules.Actor(actor);owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);CreditApplicationRules.Id(commandId);CreditUpfrontRules.Input(input);var b=await Source(owner,order,ct);await CommandGate(actor,commandId,ct);var hash=CreditApplicationRules.Hash(Json(new{owner,order,input}));var prior=await Commands.SingleOrDefaultAsync(x=>x.ActorId==actor&&x.CommandId==commandId,ct);if(prior is not null){if(prior.OwnerId!=owner||prior.OrderId!=order||prior.PayloadHash!=hash)throw new BusinessException("credit_upfront_idempotency_conflict","This upfront command belongs to another body or order.");return Receipt(prior)with{Replayed=true};}
        var account=await Confirmations(order).SingleOrDefaultAsync(ct);var history=account is null?[]:await VerifiedEvents(account,b,ct);var latest=history.LastOrDefault();var now=clock.GetUtcNow().ToUniversalTime();RequireState(b,input,latest,now);var next=CreditUpfrontRules.Next(latest?.Summary.State,input.Action,b.Required);if(history.Length>=CreditUpfrontRules.MaximumEvents)throw new BusinessException("credit_upfront_capacity_conflict","The upfront history reached its technical capacity.");if(input.OccurredAt<(input.AcknowledgedCommittedOrder?b.Source.CreatedAt:latest?.Summary.OccurredAt??b.Source.CreatedAt)||input.OccurredAt>now||now<(latest?.Summary.RecordedAt??b.Source.CreatedAt))throw CreditUpfrontRules.Invalid();
        if(account is null){account=new(){OwnerId=owner,OrderId=order,OriginalScheduleId=b.Schedule!.Id,QuoteFingerprint=b.Source.QuoteFingerprint,FinancialHash=CreditScheduleFacts.FinancialHash(b.Source),RequiredAmountRial=b.Required,ActorId=actor,RecordedAt=now};account.ProtectedOrigin=protection.Protect("origin",owner,order,account.Id,Json(OriginData(account)));db.UpfrontConfirmations.Add(account);await db.SaveChangesAsync(ct);}
        var e=new CreditUpfrontEvent{ConfirmationId=account.Id,OrderId=order,ScheduleId=b.Schedule!.Id,Sequence=history.Length+1,Action=input.Action,State=next,RequiredAmountRial=b.Required,AcknowledgedAmountRial=CreditUpfrontRules.Acknowledged(next,b.Required),ActorId=actor,OccurredAt=input.OccurredAt,RecordedAt=now};var seal=new EventSeal(e.Id,e.ConfirmationId,order,e.ScheduleId,e.Sequence,e.Action,e.State,e.RequiredAmountRial,e.AcknowledgedAmountRial,actor,e.OccurredAt,e.RecordedAt,input.OrderVersion,input.ScheduleVersion,input.Version,input.Reference,input.Note,input.AcknowledgedClosedOrder,input.AcknowledgedCommittedOrder);e.ProtectedEvent=protection.Protect("event",owner,order,e.Id,Json(seal));db.UpfrontEvents.Add(e);await db.SaveChangesAsync(ct);var d=EventData(account,e).Data;var result=new CreditUpfrontResult(1,commandId,order,d,false);var raw=Json(result);db.UpfrontCommands.Add(new(){ActorId=actor,CommandId=commandId,OwnerId=owner,OrderId=order,ConfirmationId=account.Id,EventId=e.Id,PayloadHash=hash,ResultHash=CreditApplicationRules.Hash(raw),ProtectedResult=protection.Protect("receipt",actor,order,commandId,raw),At=now});await db.SaveChangesAsync(ct);await EnsureCommitAsync(owner,order,input,ct);return result;
    }
    private static void RequireState(Basis b,CreditUpfrontInput input,CreditUpfrontEventData? latest,DateTimeOffset now)
    {
        if(b.Source.OrderVersion!=input.OrderVersion||b.Schedule is null||b.Schedule.Version!=input.ScheduleVersion||latest?.Summary.Version!=input.Version)throw CreditUpfrontRules.Conflict();if(b.Source.State=="CreditApproved"){if(!b.CommittedAmendable||!input.AcknowledgedCommittedOrder||latest is null)throw CreditUpfrontRules.Conflict();}else{if(input.AcknowledgedCommittedOrder)throw CreditUpfrontRules.Conflict();if(input.Action=="RevokeConfirmation"){if(!AmendableState(b.Source)||!Open(b.Source,now)&&!input.AcknowledgedClosedOrder)throw CreditUpfrontRules.Conflict();}else if(!Open(b.Source,now))throw CreditUpfrontRules.Conflict();}
    }
    public async Task EnsureCommitAsync(string owner,string order,CreditUpfrontInput input,CancellationToken ct)
    {
        var b=await Source(owner,order,ct);if(b.Source.OrderVersion!=input.OrderVersion||b.Schedule?.Version!=input.ScheduleVersion)throw CreditUpfrontRules.Conflict();if(b.Source.State=="CreditApproved"){if(!b.CommittedAmendable||!input.AcknowledgedCommittedOrder)throw CreditUpfrontRules.Conflict();}else{if(input.AcknowledgedCommittedOrder)throw CreditUpfrontRules.Conflict();if(input.Action=="RevokeConfirmation"){if(!AmendableState(b.Source)||!Open(b.Source,clock.GetUtcNow())&&!input.AcknowledgedClosedOrder)throw CreditUpfrontRules.Conflict();}else if(!Open(b.Source,clock.GetUtcNow()))throw CreditUpfrontRules.Conflict();}
    }
    public async Task<CreditUpfrontResult> ReceiptAsync(string actor,string owner,string order,string commandId,CancellationToken ct)
    {
        actor=CreditApplicationRules.Actor(actor);owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);CreditApplicationRules.Id(commandId);var c=await db.UpfrontCommands.AsNoTracking().SingleOrDefaultAsync(x=>x.ActorId==actor&&x.OwnerId==owner&&x.OrderId==order&&x.CommandId==commandId,ct)??throw CreditApplicationRules.Missing();return Receipt(c)with{Replayed=true};
    }
    public async Task<CreditUpfrontPage> PageAsync(string owner,string order,bool writable,CancellationToken ct)
    {
        var b=await Source(owner,order,ct);var c=await Confirmations(order).SingleOrDefaultAsync(ct);var rows=c is null?[]:await VerifiedEvents(c,b,ct);var current=rows.LastOrDefault()?.Summary;var blockers=new List<string>();var committed=b.Source.State=="CreditApproved";if(committed&&c is null)throw CreditUpfrontRules.Unavailable();var open=Open(b.Source,clock.GetUtcNow())||b.CommittedAmendable;if(!open)blockers.Add(committed?"shipment_already_dispatched":"order_closed");if(b.Schedule is null)blockers.Add("schedule_required");if(rows.Length>=CreditUpfrontRules.MaximumEvents)blockers.Add("history_capacity");var fresh=current is null||current.State=="Revoked";var canConfirm=writable&&blockers.Count==0&&fresh;var canRevoke=writable&&b.Schedule is not null&&rows.Length<CreditUpfrontRules.MaximumEvents&&current?.State is("ReceiptConfirmed"or"NoUpfrontDue")&&(AmendableState(b.Source)||b.CommittedAmendable);return new(1,order,b.Source.OrderVersion,b.Source.State,CreditUpfrontRules.Rial(b.Required),b.Schedule?.Version,current,canConfirm&&b.Required>0,canConfirm&&b.Required==0,canRevoke,blockers.ToArray());
    }
    public async Task<CreditUpfrontCustomerPage> CustomerAsync(string owner,string order,CancellationToken ct){var p=await PageAsync(owner,order,false,ct);return new(1,order,p.RequiredAmountRial,p.Current);}
    public async Task<CreditUpfrontHistory> HistoryAsync(string owner,string order,int? before,CancellationToken ct)
    {
        if(before is<1 or>CreditUpfrontRules.MaximumEvents)throw CreditUpfrontRules.Invalid();var b=await Source(owner,order,ct);var c=await Confirmations(order).SingleOrDefaultAsync(ct);var all=c is null?[]:await VerifiedEvents(c,b,ct);var rows=all.Where(x=>before==null||x.Summary.Sequence<before).OrderByDescending(x=>x.Summary.Sequence).Take(21).ToArray();return new(1,order,rows.Take(20).ToArray(),rows.Length>20?rows[19].Summary.Sequence:null);
    }
    private async Task CommandGate(string actor,string commandId,CancellationToken ct)
    {
        var tx=db.Database.CurrentTransaction!;await using var command=db.Database.GetDbConnection().CreateCommand();command.Transaction=tx.GetDbTransaction();command.CommandTimeout=15;command.CommandText="DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource=@resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000; SELECT @r;";var p=command.CreateParameter();p.ParameterName="@resource";p.Value="sayman:credit:upfront-command:v1:"+CreditApplicationRules.Hash(actor+":"+commandId);command.Parameters.Add(p);if(Convert.ToInt32(await command.ExecuteScalarAsync(ct),CultureInfo.InvariantCulture)<0)throw new BusinessException("credit_upfront_busy","Retry the same upfront command.");
    }
}
